      isCur: !!((cur && g.runId === cur) || (Recall.on() && (rc.setId ? g.setId === rc.setId : rc.runId && g.runId === rc.runId))),
      resumable: !!(r && ["running", "review", "paused", "stopped"].includes(r.status) && r.runId !== cur),
