    SheetWin.drawOrder(cv, target, "", { back: true, thumb: true, onInfo: inf => { host._info = inf; }, onWait: t => say(t), onProgress: (dn, n) => say(dn < n ? `Reading design ${dn + 1} of ${n}…` : null) })
